// Original task list with estimated hours
record Task(String name, int hoursEstimate, Priority priority) {}

enum Priority { CRITICAL, HIGH, MEDIUM, LOW }

public class DeadlineResponse {
    public List<Task> prioritizeUnderPressure(List<Task> allTasks, int availableHours) {
        // Step 1: Separate critical from nice-to-have
        var criticalTasks = allTasks.stream()
            .filter(t -> t.priority() == Priority.CRITICAL)
            .toList();

        // Step 2: Calculate if critical path fits in time
        int criticalHours = criticalTasks.stream()
            .mapToInt(Task::hoursEstimate)
            .sum();

        if (criticalHours > availableHours) {
            // Communicate risk immediately, negotiate scope
            notifyStakeholders("Critical tasks need " + criticalHours + " hours, we have " + availableHours);
        }

        // Step 3: Return prioritized list
        return allTasks.stream()
            .sorted(Comparator.comparing(Task::priority))
            .toList();
    }

