// Example: Debugging a NullPointerException in a Spring REST API
@RestController
public class OrderController {
    private final OrderService orderService;

    public OrderController(OrderService orderService) {
        this.orderService = orderService;
    }

    @GetMapping("/orders/{id}")
    public ResponseEntity<Order> getOrder(@PathVariable Long id) {
        // Step 1: Reproduce the error consistently
        // Found NPE when id=999 (non-existent order)

        // Step 2: Trace execution flow
        var order = orderService.findById(id);

        // Step 3: Identify failure point
        // orderService.findById() returned null instead of Optional

        // Step 4: Apply fix
        if (order == null) {
            return ResponseEntity.notFound().build();
        }
        return ResponseEntity.ok(order);
    }
}

// Better approach after debugging
@GetMapping("/orders/{id}")
public ResponseEntity<Order> getOrderFixed(@PathVariable Long id) {
    return orderService.findById(id)
        .map(ResponseEntity::ok)
        .orElse(ResponseEntity.notFound().build());
}
