// Original code submitted for review
public class UserService {
    public void updateUser(Long userId, String name, String email) {
        User user = userRepository.findById(userId).get(); // Reviewer flagged this
        user.setName(name);
        user.setEmail(email);
        userRepository.save(user);
    }
}

// Reviewer comment: "What happens if userId doesn't exist? .get() throws NoSuchElementException."
// My initial reaction: "The controller validates the ID exists, so this is safe."
// Reviewer response: "Controller validation can be bypassed, always handle Optional safely."

// Revised code after accepting feedback
public class UserService {
    public void updateUser(Long userId, String name, String email) {
        User user = userRepository.findById(userId)
            .orElseThrow(() -> new UserNotFoundException("User not found: " + userId));

        user.setName(name);
        user.setEmail(email);
        userRepository.save(user);
    }
}

// Additional feedback: "Consider validating email format before saving."
// Implemented without pushback, learned to validate inputs at service layer
