// Initial attempt: race condition bug I struggled with
public class CounterService {
    private int count = 0; // Shared mutable state

    public void increment() {
        count++; // Not atomic! Read-modify-write race condition
    }

    public int getCount() {
        return count;
    }
}

// After learning about thread safety, fixed version
import java.util.concurrent.atomic.AtomicInteger;

public class CounterServiceFixed {
    private final AtomicInteger count = new AtomicInteger(0);

    public void increment() {
        count.incrementAndGet(); // Thread-safe atomic operation
    }

    public int getCount() {
        return count.get();
    }
}

